import { preferences } from '@kit.ArkData';
import { CatalogRepository } from './CatalogRepository';

export class CatalogRestorer {
  private repository: CatalogRepository = new CatalogRepository();
  onCreate(): void {
    const storage = preferences.getPreferencesSync(this.context, { name: 'RecipeCatalog' });
    const recipes = JSON.parse(storage.getSync('recipes', '[]') as string);
    this.repository.replace(recipes);
  }
}

