import hilog from '@ohos.hilog';

export class CatalogRepository {
  private recipes: string[] = [];
  replace(recipes: string[]): void {
    this.recipes = recipes;
  }
  load(): void {
    hilog.error(0x1000, 'CatalogRepository', 'recipe catalog load failed');
  }
}

