import { preferences } from '@kit.ArkData';

export class DeferredReader {
  schedule(context: Context): void {
    queueMicrotask(() => {
      const storage = preferences.getPreferencesSync(context, { name: 'RecipeCatalog' });
      const recipes = JSON.parse(storage.getSync('recipes', '[]') as string);
      consume(recipes);
    });
  }
}
